          "text": "En esta etapa de la misión profundizaremos en: Temperaturas Extremas sin Atmósfera.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Los siete planetas descubiertos en órbita alrededor de la estrella enana roja TRAPPIST-1 podrían caber fácilmente dentro de la órbita de Mercurio, el planeta más interno de nuestro sistema solar. De hecho, tendrían espacio de sobra. TRAPPIST-1 también tiene sólo una fracción del tamaño de nuestro sol; no es mucho más grande que Júpiter. Entonces, las proporciones del sistema TRAPPIST-1 se parecen más a las de Júpiter y sus lunas que a las de nuestro sistema solar.  Los siete planetas de TRAPPIST-1 son todos terrestres y del tamaño de la Tierra, según una investigación publicada en 2017 en la revista Nature. TRAPPIST-1 es una estrella enana ultrafría en la constelación de Acuario y sus planetas orbitan muy cerca de ella.  El sistema ha sido revelado a través de observaciones f...\"",
