          "text": "En esta etapa de la misión profundizaremos en: Los Cráteres: Cicatrices del Sistema Solar.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Esta es la primera imagen de la Tierra tomada desde otro planeta que realmente muestra nuestro hogar como un disco planetario. Debido a que la Tierra y la Luna están más cerca del Sol que Marte, exhiben fases, tal como lo hacen la Luna, Venus y Mercurio cuando se ven desde la Tierra.\"",
          "image": "https://images-assets.nasa.gov/image/PIA04531/PIA04531~small.jpg"
