          "text": "En esta etapa de la misión profundizaremos en: Hielo en el Planeta de Fuego.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Esta imagen NAC de alta resolución muestra una vista del terminador del amanecer de Mercurio, la división entre el lado diurno iluminado por el sol y el lado nocturno oscuro del planeta, como se ve cuando la nave espacial MESSENGER abandonó el planeta durante el segundo sobrevuelo de la misión a Mercurio.\"",
          "image": "https://images-assets.nasa.gov/image/PIA12045/PIA12045~small.jpg"
