        {
          "title": "Posibilidad de Vida en las Nubes",
          "text": "En esta etapa de la misión profundizaremos en: Posibilidad de Vida en las Nubes.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"El viaje de siete años a Saturno comenzó con el despegue de un Titán IVB/Centaur que transportaba la sonda Cassini y su sonda Huygens adjunta. Después de un viaje de 2.200 millones de millas que incluyó dos acercamientos a Venus y uno a la Tierra para ganar velocidad adicional, la nave espacial de dos pisos de altura llegará a Saturno en julio de 2004. El orbitador orbitará el planeta durante 4 años, acompañado de 12 instrumentos científicos que recopilarán datos sobre la atmósfera, los anillos y la magnetosfera de Saturno, y realizarán observaciones de cerca de las lunas de Saturno. Huygens, con un conjunto separado de 6 instrumentos científicos, se separará de Cassini para volar en una trayectoria balística hacia Titán, el único cuerpo celeste además...\"",
          "image": "https://images-assets.nasa.gov/image/9710531/9710531~small.jpg"
        },
        {
          "title": "El Interior de Venus: Un Mundo de Roca",
          "text": "En esta etapa de la misión profundizaremos en: El Interior de Venus: Un Mundo de Roca.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"El viaje de siete años a Saturno comenzó con el despegue de un Titán IVB/Centaur que transportaba la sonda Cassini y su sonda Huygens adjunta. Después de un viaje de 2.200 millones de millas que incluyó dos acercamientos a Venus y uno a la Tierra para ganar velocidad adicional, la nave espacial de dos pisos de altura llegará a Saturno en julio de 2004. El orbitador orbitará el planeta durante 4 años, acompañado de 12 instrumentos científicos que recopilarán datos sobre la atmósfera, los anillos y la magnetosfera de Saturno y realizarán observaciones de cerca de sus lunas. Huygens, con un conjunto separado de 6 instrumentos científicos, se separará de Cassini para volar en una trayectoria balística hacia Titán, el único cuerpo celeste además...\"",
          "image": "https://images-assets.nasa.gov/image/9710527/9710527~small.jpg"
        },
        {
          "title": "Sin Campo Magnético: Venus Desprotegido",
          "text": "En esta etapa de la misión profundizaremos en: Sin Campo Magnético: Venus Desprotegido.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"art002e000192 (3 de abril de 2026) - Esta fotografía nocturna de la Tierra fue tomada el 2 de abril de 2026 por un miembro de la tripulación Artemis II apuntando una cámara a través de una ventana de la nave espacial Orion. La imagen fue capturada después de que Orión completara su inyección translunar, la maniobra crítica que envió a la nave espacial en su camino hacia la Luna y de regreso. El hemisferio visible parece inundado de luz solar, pero en realidad está iluminado por la luz de la luna, la luz del sol reflejada desde la superficie lunar. A lo largo de los bordes superior izquierdo (sur) e inferior derecho (norte) del disco de la Tierra, las auroras verdes brillan contra el cielo oscuro, mostrando partículas cargadas del Sol interactuando con los gases de la atmósfera terrestre.  África es visible en la l...\"",
          "image": "https://images-assets.nasa.gov/image/art002e000192/art002e000192~large.jpg"
        },
        {
          "title": "La Rotación Retrógrada: El Sol Nace por el Oeste",
          "text": "En esta etapa de la misión profundizaremos en: La Rotación Retrógrada: El Sol Nace por el Oeste.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Este gráfico muestra, en la fila superior, conceptos artísticos de los siete planetas de TRAPPIST-1 con sus períodos orbitales, distancias a sus estrellas, radios, masas, densidades y gravedad superficial en comparación con los de la Tierra. Estos números están actualizados a febrero de 2018. En la fila inferior, se muestran los mismos números para los cuerpos de nuestro sistema solar interior: Mercurio, Venus, la Tierra y Marte. Los planetas TRAPPIST-1 orbitan su estrella muy cerca, con períodos que van desde 1,5 hasta sólo unos 20 días. Esto es mucho más corto que el período de Mercurio, que orbita alrededor de nuestro sol en unos 88 días.  Las masas y densidades de los planetas TRAPPIST-1 fueron determinadas mediante mediciones cuidadosas de ligeras variaciones...\"",
          "image": "https://images-assets.nasa.gov/image/PIA22094/PIA22094~medium.jpg"
        },
        {
          "title": "El Efecto Invernadero Extremo",
          "text": "En esta etapa de la misión profundizaremos en: El Efecto Invernadero Extremo.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Los Juegos Olímpicos de Invierno de 2002 se celebran en Salt Lake City en varios lugares dentro de la ciudad, en ciudades cercanas y dentro de las montañas Wasatch adyacentes. Esta vista en perspectiva tridimensional, en colores naturales simulados, presenta una vista de finales de primavera sobre Salt Lake City hacia las montañas nevadas Wasatch hacia el este. La imagen fue creada colocando datos de imágenes ASTER sobre datos de topografía digital de los Datos de Elevación Nacional del Servicio Geológico de EE. UU.  Esta imagen fue adquirida el 28 de mayo de 2000 por el Radiómetro Avanzado de Reflexión y Emisión Térmica Espacial (ASTER) en el satélite Terra de la NASA. Con sus 14 bandas espectrales desde la región de longitud de onda visible hasta la región de longitud de onda infrarroja térmica, y su alta r espacial...\"",
          "image": "https://images-assets.nasa.gov/image/PIA03466/PIA03466~small.jpg"
        },
        {
          "title": "Las Sondas Venera: Sobrevivir el Infierno",
          "text": "En esta etapa de la misión profundizaremos en: Las Sondas Venera: Sobrevivir el Infierno.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Los Juegos Olímpicos de Invierno de 2002 se celebran en Salt Lake City en varios lugares dentro de la ciudad, en ciudades cercanas y dentro de las montañas Wasatch adyacentes. Esta imagen en color natural simulada presenta una vista invernal nevada del centro norte de Utah que incluye todos los sitios olímpicos. La imagen se extiende desde Ogden en el norte hasta Provo en el sur; e incluye las montañas nevadas Wasatch y la parte oriental del Gran Lago Salado.  Esta imagen fue adquirida el 8 de febrero de 2001 por el Radiómetro Avanzado de Reflexión y Emisión Térmica Espacial (ASTER) en el satélite Terra de la NASA. Con sus 14 bandas espectrales desde la región de longitud de onda visible hasta la región de longitud de onda infrarroja térmica, y su alta resolución espacial...\"",
          "image": "https://images-assets.nasa.gov/image/PIA03465/PIA03465~medium.jpg"
        },
        {
          "title": "Los Volcanes de Venus: Un Mundo Volcánico Activo",
          "text": "En esta etapa de la misión profundizaremos en: Los Volcanes de Venus: Un Mundo Volcánico Activo.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Los Juegos Olímpicos de Invierno de 2002 se celebran en Salt Lake City en varios lugares dentro de la ciudad, en ciudades cercanas y dentro de las montañas Wasatch adyacentes. Esta imagen en color natural simulada presenta una vista de finales de primavera del centro norte de Utah que incluye todos los sitios olímpicos. La imagen se extiende desde Ogden en el norte hasta Provo en el sur; e incluye las montañas nevadas Wasatch y la parte oriental del Gran Lago Salado.  Esta imagen fue adquirida el 28 de mayo de 2000 por el Radiómetro Avanzado de Reflexión y Emisión Térmica Espacial (ASTER) en el satélite Terra de la NASA. Con sus 14 bandas espectrales desde la región de longitud de onda visible hasta la región de longitud de onda infrarroja térmica, y su alta resolución espacial de...\"",
          "image": "https://images-assets.nasa.gov/image/PIA03464/PIA03464~medium.jpg"
        },
        {
          "title": "Las Nubes de Ácido Sulfúrico",
          "text": "En esta etapa de la misión profundizaremos en: Las Nubes de Ácido Sulfúrico.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Concepto artístico de la nave espacial Magallanes haciendo un mapa de radar de Venus.  Magallanes cartografió el 98 por ciento de la superficie de Venus con una resolución de 100 a 150 metros (aproximadamente la longitud de un campo de fútbol), utilizando un radar de apertura sintética, una técnica que simula el uso de una antena de radar mucho más grande. Descubrió que el 85 por ciento de la superficie está cubierta de flujos volcánicos y mostró evidencia de movimientos tectónicos, vientos turbulentos en la superficie, canales de lava y cúpulas en forma de panqueque. Magallanes también produjo datos de gravedad de alta resolución para el 95 por ciento del planeta y probó una nueva técnica de maniobra llamada aerofrenado, utilizando la resistencia atmosférica para ajustar su órbita.  La nave espacial fue comandada...\"",
          "image": "https://images-assets.nasa.gov/image/PIA18175/PIA18175~thumb.jpg"
        },
        {
          "title": "La Misión DAVINCI y EnVision: Regreso a Venus",
          "text": "En esta etapa de la misión profundizaremos en: La Misión DAVINCI y EnVision: Regreso a Venus.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Esta imagen de Chandra, la primera imagen de rayos X jamás tomada de Venus, muestra una media luna debido a la orientación relativa del Sol, la Tierra y Venus. Los rayos X son producidos por la radiación fluorescente del oxígeno y otros átomos en la atmósfera entre 120 y 140 kilómetros sobre la superficie del planeta. Por el contrario, la luz óptica de Venus es causada por el reflejo de las nubes entre 50 y 70 kilómetros sobre la superficie.\"",
          "image": "https://images-assets.nasa.gov/image/0301101/0301101~medium.jpg"
        },
        {
          "title": "Venus y la Tierra: Gemelos Diferentes",
          "text": "En esta etapa de la misión profundizaremos en: Venus y la Tierra: Gemelos Diferentes.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Este concepto artístico ilustra el planeta más caliente observado hasta ahora en el universo. La abrasadora bola de gas, un Júpiter caliente llamado HD 149026b, es aproximadamente 3 veces más caliente que la superficie rocosa de Venus, el planeta más caliente de nuestro sistema solar.\"",
          "image": "https://images-assets.nasa.gov/image/PIA09378/PIA09378~thumb.jpg"
        }
