          "text": "En esta etapa de la misión profundizaremos en: Un Banquete Demasiado Rápido.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"En esta fotografía, los instrumentos del Observatorio Astro-1 están instalados en la bodega de carga del orbitador Columbia. Astro-1 fue lanzado a bordo de la misión Space Shuttle Orbiter Columbia (STS-35) el 2 de diciembre de 1990. El Astro Observatorio fue diseñado para explorar el universo observando y midiendo la radiación ultravioleta de los objetos celestes. Los objetivos astronómicos de observación seleccionados para las misiones Astro incluían planetas, estrellas, cúmulos de estrellas, galaxias, cúmulos de galaxias, cuásares, restos de estrellas que explotaron (supernovas), nubes de gas y polvo (nebulosas) y el medio interestelar. Astro-1 utilizó un sistema de paletas Spacelab con un sistema de orientación de instrumentos y una estructura cruciforme...\"",
