        {
          "title": "Las Moscas de Fruta: Los Primeros Astronautas",
          "text": "En esta etapa de la misión profundizaremos en: Las Moscas de Fruta: Los Primeros Astronautas.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss065e093501 (7 de junio de 2021) --- La astronauta de la NASA Megan McArthur instala un nuevo ADSEP-2 (Procesador de experimentos espaciales avanzado-2) que contiene muestras de ADSEP-UMAMI dentro del módulo de laboratorio Kibo a bordo de la Estación Espacial Internacional (ISS).  La investigación Comprensión de la microgravedad en las interacciones entre animales y microbios (UMAMI) examina los efectos de los vuelos espaciales en las interacciones moleculares y químicas entre los microbios beneficiosos y sus huéspedes animales.  La instalación ADSEP-2 admite observaciones de muestras biológicas o físicas y también puede operarse a bordo de los barcos de reabastecimiento Cargo Dragon y Northrop Grumman Cygnus.\"",
          "image": "https://images-assets.nasa.gov/image/iss065e093501/iss065e093501~medium.jpg"
        },
        {
          "title": "Los Ratones: Más All? de las Moscas",
          "text": "En esta etapa de la misión profundizaremos en: Los Ratones: Más All? de las Moscas.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss065e093508 (7 de junio de 2021) --- La astronauta de la NASA Megan McArthur instala un nuevo ADSEP-2 (Procesador de experimentos espaciales avanzado-2) que contiene muestras de ADSEP-UMAMI dentro del módulo de laboratorio Kibo a bordo de la Estación Espacial Internacional (ISS).  La investigación Comprensión de la microgravedad en las interacciones entre animales y microbios (UMAMI) examina los efectos de los vuelos espaciales en las interacciones moleculares y químicas entre los microbios beneficiosos y sus huéspedes animales.  La instalación ADSEP-2 admite observaciones de muestras biológicas o físicas y también puede operarse a bordo de los barcos de reabastecimiento Cargo Dragon y Northrop Grumman Cygnus.\"",
          "image": "https://images-assets.nasa.gov/image/iss065e093508/iss065e093508~medium.jpg"
        },
        {
          "title": "Los Monos Americanos: El Programa de Primates",
          "text": "En esta etapa de la misión profundizaremos en: Los Monos Americanos: El Programa de Primates.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss065e093498 (7 de junio de 2021) --- La astronauta de la NASA Megan McArthur instala un nuevo ADSEP-2 (Procesador de experimentos espaciales avanzado-2) que contiene muestras de ADSEP-UMAMI dentro del módulo de laboratorio Kibo a bordo de la Estación Espacial Internacional (ISS).  La investigación Comprensión de la microgravedad en las interacciones entre animales y microbios (UMAMI) examina los efectos de los vuelos espaciales en las interacciones moleculares y químicas entre los microbios beneficiosos y sus huéspedes animales.  La instalación ADSEP-2 admite observaciones de muestras biológicas o físicas y también puede operarse a bordo de los barcos de reabastecimiento Cargo Dragon y Northrop Grumman Cygnus.\"",
          "image": "https://images-assets.nasa.gov/image/iss065e093498/iss065e093498~medium.jpg"
        },
        {
          "title": "Las Tortugas Soviéticas: Las Primeras en ?rbita Completa y Regreso",
          "text": "En esta etapa de la misión profundizaremos en: Las Tortugas Soviéticas: Las Primeras en ?rbita Completa y Regreso.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"jsc2021e019403 (29/1/2021) --- Un casete de procesamiento de fluidos Techshot que forma parte de la flota ADSEP de instalaciones de hardware para vuelos espaciales de Techshot. El casete de material de vuelo está cargado con pequeñas bolsas de acuario que contienen los calamares bobtail juveniles. Una vez lanzadas al espacio, las bolsas del acuario serán inoculadas con una bacteria luminiscente para iniciar la simbiosis normal con el calamar.  La comprensión de la microgravedad en las interacciones entre animales y microbios (UMAMI) examina los efectos de los vuelos espaciales en las interacciones moleculares y químicas entre los microbios beneficiosos y sus huéspedes animales.  Imagen cortesía de Rachel Ormsby.\"",
          "image": "https://images-assets.nasa.gov/image/jsc2021e019403/jsc2021e019403~medium.jpg"
        },
        {
          "title": "Los Peces en Microgravedad",
          "text": "En esta etapa de la misión profundizaremos en: Los Peces en Microgravedad.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss056e139457 (15 de agosto de 2018) --- El cosmonauta de Roscosmos Sergey Prokopyev despliega manualmente uno de los dos nanosatélites Tanyusha justo afuera de la esclusa de aire del compartimiento de acoplamiento Pirs durante una caminata espacial que duró 7 horas y 46 minutos. Su compañero cosmonauta Oleg Artemyev (fuera de cuadro) se unió a Prokopyev durante la caminata espacial en la que también se instaló el experimento de seguimiento de animales Ícaro y la recuperación de un experimento de exposición de materiales en el segmento ruso de la Estación Espacial Internacional.\"",
          "image": "https://images-assets.nasa.gov/image/iss056e139457/iss056e139457~medium.jpg"
        },
        {
          "title": "Las Ranas en el Espacio: El Experimento Otolith",
          "text": "En esta etapa de la misión profundizaremos en: Las Ranas en el Espacio: El Experimento Otolith.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss070e037585 (11 de diciembre de 2023) --- Loral O'Hara, astronauta de la NASA e ingeniero de vuelo de la Expedición 70, muestra el hardware de investigación que respalda el experimento de biología espacial UMAMI, o Comprensión de la microgravedad en la interacción animal-microbio. O'Hara posee el casete de procesamiento de fluidos (FPC) del procesador de experimentos espaciales avanzado (ADSEP) que respalda la observación de los efectos de los vuelos espaciales en las interacciones moleculares y químicas entre los microbios beneficiosos y sus huéspedes animales.\"",
          "image": "https://images-assets.nasa.gov/image/iss070e037585/iss070e037585~medium.jpg"
        },
        {
          "title": "Los Efectos de la Microgravedad en los Animales",
          "text": "En esta etapa de la misión profundizaremos en: Los Efectos de la Microgravedad en los Animales.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss053e215867 (20 de noviembre de 2017) --- El EcAMSat, abreviatura de E. coli AntiMicrobial Satellite, se ve momentos después de ser expulsado del NanoRacks CubeSat Deployer conectado al exterior del módulo de laboratorio Kibo de la Agencia de Exploración Aeroespacial de Japón. La misión E. coli AntiMicrobial Satellite (EcAMSat) investigará los efectos de la microgravedad espacial sobre la resistencia a los antibióticos de E. coli, una bacteria patógena responsable de la infección del tracto urinario en humanos y animales.\"",
          "image": "https://images-assets.nasa.gov/image/iss053e215867/iss053e215867~medium.jpg"
        },
        {
          "title": "Las Arañas en la ISS: ?Cómo Tejen en Ingravidez?",
          "text": "En esta etapa de la misión profundizaremos en: Las Arañas en la ISS: ?Cómo Tejen en Ingravidez?.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss056e142981 (15 de agosto de 2018) --- El cosmonauta de Roscosmos Sergey Prokopyev tiende el cable para la instalación del experimento de seguimiento de animales Ícaro en el módulo de servicio Zvezda durante una caminata espacial que duró 7 horas 46 minutos. Su compañero cosmonauta Oleg Artemyev (fuera de cuadro) se unió a Prokopyev durante la caminata espacial que también vio el despliegue de cuatro nanosatélites y la recuperación de un experimento de exposición de materiales en el segmento ruso de la Estación Espacial Internacional.\"",
          "image": "https://images-assets.nasa.gov/image/iss056e142981/iss056e142981~medium.jpg"
        },
        {
          "title": "El Legado de los Animales Pioneros",
          "text": "En esta etapa de la misión profundizaremos en: El Legado de los Animales Pioneros.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss074e0316004 (18 de febrero de 2026) --- El astronauta de la NASA e ingeniero de vuelo de la Expedición 74, Chris Williams, intercambia componentes de computadora dentro del hardware científico en el módulo de laboratorio Kibo de la Estación Espacial Internacional. El equipo de investigación permite estudiar los efectos de los vuelos espaciales sobre las interacciones moleculares y químicas entre los microbios beneficiosos y sus huéspedes animales para ayudar a preservar la salud de los astronautas en misiones espaciales de larga duración. Crédito: NASA/Jack Hathaway\"",
          "image": "https://images-assets.nasa.gov/image/iss074e0316004/iss074e0316004~large.jpg"
        }
