          "text": "En esta etapa de la misión profundizaremos en: El Meteorito de Chelyabinsk.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"Un cohete Atlas V de United Launch Alliance despega del Complejo de Lanzamiento Espacial 41 en la Estación de la Fuerza Aérea de Cabo Cañaveral transportando una nave espacial de reabastecimiento Orbital ATK Cygnus en una misión comercial de servicios de reabastecimiento a la Estación Espacial Internacional. El despegue fue a las 11:05 p.m. hora del Este. Cygnus entregará la segunda generación de una impresora portátil a bordo para demostrar la impresión 3D, un instrumento para las primeras observaciones espaciales de la composición química de los meteoros que ingresan a la atmósfera de la Tierra y un experimento para estudiar cómo arden los incendios en microgravedad.\"",
