          "text": "En esta etapa de la misión profundizaremos en: Micrometeoritos: El Polvo Cósmico.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"iss047e126086 (20/5/2016) --- Vista durante la configuración e instalación del meteorito, en el laboratorio de EE. UU., instalado en el Centro de investigación observacional de Window (WORF). La investigación Meteor proporciona la primera medición espacial del flujo de meteoritos. También permite el seguimiento de compuestos a base de carbono. La medición continua de las interacciones de los meteoritos con la atmósfera terrestre también podría detectar lluvias de meteoritos imprevistas anteriormente.\"",
