          "text": "En esta etapa de la misión profundizaremos en: El Futuro: OSIRIS-APEX y Apophis.\n\nA continuación, analizamos los datos científicos recopilados por la NASA referentes a este entorno astronómico:\n\n\"El viernes 10 de agosto de 2018, en la Estación de la Fuerza Aérea de Cabo Cañaveral en Florida, el cohete pesado Delta IV de United Launch Alliance está listo para impulsar la sonda solar Parker de la NASA en una misión para estudiar el Sol luego del retroceso del pórtico de la torre de servicio móvil en el Complejo de lanzamiento espacial 37. La sonda solar Parker realizará las observaciones más cercanas de una estrella cuando viaja a través de la atmósfera del Sol, llamada corona. La sonda se basará en mediciones e imágenes para revolucionar nuestra comprensión de la corona y la conexión Sol-Tierra.\"",
